package com.happybananas.tracezilla.workflow;
import com.happybananas.tracezilla.shared.*; import java.util.*;
public final class CompareCatalogs {private final CatalogReader shopify,tracezilla;public CompareCatalogs(CatalogReader shopify,CatalogReader tracezilla){this.shopify=shopify;this.tracezilla=tracezilla;}public Result run(int limit)throws Exception{if(limit<1)throw new IllegalArgumentException("The display limit must be positive.");var left=new TreeSet<>(shopify.read().stream().map(CatalogItem::sku).toList());var right=new TreeSet<>(tracezilla.read().stream().map(CatalogItem::sku).toList());var both=new TreeSet<>(left);both.retainAll(right);var onlyLeft=new TreeSet<>(left);onlyLeft.removeAll(right);var onlyRight=new TreeSet<>(right);onlyRight.removeAll(left);return new Result(limit,List.copyOf(both),List.copyOf(onlyLeft),List.copyOf(onlyRight));}public record Result(int displayLimit,List<String> presentInBoth,List<String> onlyInShopify,List<String> onlyInTracezilla){public String status(){return onlyInShopify.isEmpty()&&onlyInTracezilla.isEmpty()?"match":"differences";}}}
